/* Test de la moyenne : distribution normale sous H0 + régions de rejet + statistique T */
(function () {
  var svg = document.getElementById("ht-chart");
  if (!svg) return;
  var CONF = [ [0,"90%",1.645], [1,"95%",1.960], [2,"99%",2.576] ];
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }
  function phi(x){ return Math.exp(-0.5*x*x)/Math.sqrt(2*Math.PI); }

  function draw(){
    var mu=v("ht-mu"), sig=v("ht-sig"), n=v("ht-n"), ci=CONF[v("ht-c")];
    var crit=ci[2];
    var se = sig/Math.sqrt(n);
    var T = se>0 ? mu/se : 0;
    setT("ht-mu-o", mu.toFixed(1)+"%"); setT("ht-sig-o", sig.toFixed(1)+"%"); setT("ht-n-o", n.toFixed(0)); setT("ht-c-o", ci[1]);
    setT("ht-se", se.toFixed(2)+"%"); setT("ht-t", T.toFixed(2)); setT("ht-crit", "±"+crit.toFixed(2));
    var reject = Math.abs(T) > crit;
    var dec = document.getElementById("ht-dec");
    var rejWord = al()==="en"?"Reject H₀":(al()==="nl"?"Verwerp H₀":"Rejet de H₀");
    var keepWord = al()==="en"?"Do not reject":(al()==="nl"?"Niet verwerpen":"Non-rejet");
    dec.textContent = reject ? rejWord : keepWord;
    dec.style.color = reject ? "var(--crimson)" : "var(--teal)";

    var W=520,H=240,L=20,R=20,T0=16,B=34, pw=W-L-R, ph=H-T0-B;
    var xmax=4.2;
    function px(z){ return L + (z+xmax)/(2*xmax)*pw; }
    var peak=phi(0);
    function py(d){ return T0 + (1 - d/peak)*ph; }
    var g="";
    // aires de rejet (queues au-delà de ±crit)
    function tail(sign){
      var d="M "+px(sign*crit).toFixed(1)+","+(T0+ph).toFixed(1);
      var z0=sign*crit, z1=sign*xmax, steps=40;
      for (var i=0;i<=steps;i++){ var z=z0+(z1-z0)*i/steps; d+=" L "+px(z).toFixed(1)+","+py(phi(z)).toFixed(1); }
      d+=" L "+px(sign*xmax).toFixed(1)+","+(T0+ph).toFixed(1)+" Z";
      return '<path d="'+d+'" fill="var(--crimson)" opacity="0.16"/>';
    }
    g+=tail(1); g+=tail(-1);
    // courbe normale
    var d="",N=120;
    for (var i=0;i<=N;i++){ var z=-xmax+2*xmax*i/N; d+=(i===0?"M ":" L ")+px(z).toFixed(1)+","+py(phi(z)).toFixed(1); }
    g+='<path d="'+d+'" fill="none" stroke="var(--teal)" stroke-width="2.4"/>';
    // axe
    g+='<line class="axis" x1="'+L+'" y1="'+(T0+ph)+'" x2="'+(L+pw)+'" y2="'+(T0+ph)+'"/>';
    // valeurs critiques
    [crit,-crit].forEach(function(c){
      g+='<line x1="'+px(c).toFixed(1)+'" y1="'+T0+'" x2="'+px(c).toFixed(1)+'" y2="'+(T0+ph)+'" stroke="var(--crimson)" stroke-width="1.2" stroke-dasharray="4 3"/>';
    });
    g+='<text class="tick" x="'+px(crit).toFixed(1)+'" y="'+(T0+ph+14)+'" text-anchor="middle" fill="var(--crimson)">+'+crit.toFixed(2)+'</text>';
    g+='<text class="tick" x="'+px(-crit).toFixed(1)+'" y="'+(T0+ph+14)+'" text-anchor="middle" fill="var(--crimson)">−'+crit.toFixed(2)+'</text>';
    g+='<text class="tick" x="'+px(0).toFixed(1)+'" y="'+(T0+ph+14)+'" text-anchor="middle">0</text>';
    // statistique T (clampée pour rester visible)
    var Tc=Math.max(-xmax,Math.min(xmax,T));
    g+='<line x1="'+px(Tc).toFixed(1)+'" y1="'+T0+'" x2="'+px(Tc).toFixed(1)+'" y2="'+(T0+ph)+'" stroke="var(--ink)" stroke-width="2.2"/>';
    g+='<text class="lab" x="'+px(Tc).toFixed(1)+'" y="'+(T0-4)+'" text-anchor="middle" fill="var(--ink)">T = '+T.toFixed(2)+'</text>';
    svg.innerHTML=g;
  }
  ["ht-mu","ht-sig","ht-n","ht-c"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
